// Game Night service worker (generated by tool/build_web.dart — do not edit build/web/sw.js).
// Cache-first for the app shell, engine, fonts and the four playable decks so
// that, once loaded, games run with no connection at all.
const VERSION = '__VERSION__';
const CACHE = 'game-night-' + VERSION;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((p) => new Request(p, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const old = (await caches.keys()).filter((k) => k.startsWith('game-night-') && k !== CACHE);
    // Carry the engine across deploys: re-fetch the CanvasKit files the old
    // cache held (fresh copies, since the Flutter version may have changed).
    // If the network is unavailable, keep the old copies rather than none.
    for (const name of old) {
      const prev = await caches.open(name);
      for (const req of await prev.keys()) {
        if (req.url.indexOf('/canvaskit/') === -1 || (await cache.match(req))) continue;
        try {
          await cache.add(new Request(req.url, { cache: 'reload' }));
        } catch (e) {
          const res = await prev.match(req);
          if (res) await cache.put(req, res);
        }
      }
      await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

// The page reports engine files it loaded before this worker took control.
self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type !== 'cache-runtime' || !Array.isArray(data.urls)) return;
  event.waitUntil(
    caches.open(CACHE).then(async (cache) => {
      for (const u of data.urls) {
        try {
          if (new URL(u).origin !== self.location.origin) continue;
          if (!(await cache.match(u, { ignoreSearch: true }))) await cache.add(u);
        } catch (e) { /* best effort */ }
      }
    })
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Page loads: serve the cached shell (works offline); refresh it in the background.
  if (req.mode === 'navigate') {
    event.respondWith(
      caches.open(CACHE).then(async (cache) => {
        const cached = await cache.match('./');
        const network = fetch(req).then((res) => {
          if (res.ok) cache.put('./', res.clone());
          return res;
        }).catch(() => cached);
        return cached || network;
      })
    );
    return;
  }

  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const cached = await cache.match(req, { ignoreSearch: true });
      if (cached) return cached;
      try {
        const res = await fetch(req);
        if (res.ok && url.pathname.indexOf('/sw.js') === -1) cache.put(req, res.clone());
        return res;
      } catch (e) {
        return new Response('Offline', { status: 503, statusText: 'Offline' });
      }
    })
  );
});
